<script setup>
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import InputError from '@/Components/InputError.vue';
import InputLabel from '@/Components/InputLabel.vue';
import { Head, Link, useForm } from '@inertiajs/vue3';
const props = defineProps({ event: { type: Object, required: true }, ticketType: { type: Object, default: null } });
const editing = Boolean(props.ticketType);
const form = useForm({ name: props.ticketType?.name || '', description: props.ticketType?.description || '', price: props.ticketType?.price || '', quota: props.ticketType?.quota || 0, sale_start_at: props.ticketType?.sale_start_at || '', sale_end_at: props.ticketType?.sale_end_at || '', status: props.ticketType?.status || 'active' });
function submit() { const options = { preserveScroll: true }; if (editing) form.patch(route('organizer.ticket-types.update', [props.event.id, props.ticketType.id]), options); else form.post(route('organizer.ticket-types.store', props.event.id), options); }
</script>
<template>
    <Head :title="editing ? 'Edit Ticket Type' : 'Buat Ticket Type'" /><AuthenticatedLayout><template #header><div><p class="text-xs font-bold uppercase tracking-[0.28em] text-amber-600">Event setup</p><h2 class="mt-1 text-2xl font-black tracking-tight text-slate-900">{{ editing ? 'Edit ticket type' : 'Buat ticket type' }} · {{ event.title }}</h2></div></template><div class="min-h-[calc(100vh-9rem)] bg-[#f7f3ec] px-4 py-8 sm:px-6 lg:px-8"><div class="mx-auto max-w-3xl"><form class="space-y-6 rounded-3xl border border-slate-200/80 bg-white p-6 sm:p-8" @submit.prevent="submit"><div class="grid gap-6 sm:grid-cols-2"><div class="sm:col-span-2"><InputLabel value="Nama" /><input v-model="form.name" class="mt-1 w-full rounded-xl border-slate-200" /><InputError class="mt-2" :message="form.errors.name" /></div><div class="sm:col-span-2"><InputLabel value="Deskripsi" /><textarea v-model="form.description" rows="3" class="mt-1 w-full rounded-xl border-slate-200" /><InputError class="mt-2" :message="form.errors.description" /></div><div><InputLabel value="Harga" /><input v-model="form.price" type="number" min="0" step="0.01" class="mt-1 w-full rounded-xl border-slate-200" /><InputError class="mt-2" :message="form.errors.price" /></div><div><InputLabel value="Kuota" /><input v-model="form.quota" type="number" min="0" class="mt-1 w-full rounded-xl border-slate-200" /><InputError class="mt-2" :message="form.errors.quota" /></div><div><InputLabel value="Mulai penjualan" /><input v-model="form.sale_start_at" type="datetime-local" class="mt-1 w-full rounded-xl border-slate-200" /><InputError class="mt-2" :message="form.errors.sale_start_at" /></div><div><InputLabel value="Akhir penjualan" /><input v-model="form.sale_end_at" type="datetime-local" class="mt-1 w-full rounded-xl border-slate-200" /><InputError class="mt-2" :message="form.errors.sale_end_at" /></div></div><div class="flex justify-end gap-3 border-t border-slate-100 pt-6"><Link :href="route('organizer.ticket-types.index', event.id)" class="rounded-xl px-4 py-2 text-sm font-bold text-slate-600">Batal</Link><button type="submit" :disabled="form.processing" class="rounded-xl bg-slate-950 px-5 py-2.5 text-sm font-bold text-white hover:bg-amber-600">{{ form.processing ? 'Menyimpan...' : 'Simpan ticket type' }}</button></div></form></div></div></AuthenticatedLayout>
</template>
